\begin{proposition}[Topological Manifold Structure of Projective Space]
\label{exer:1-6}




\dcref{ch1:1.6}
$\mathbb{RP}^n$ is Hausdorff and second-countable, and hence is a topological
$n$-manifold.
\end{proposition}

